/** Import-leaf brands keep read-side predicates from creating value cycles. */
export const WhereOpBrand = Symbol("WhereOpBrand");
export const CountOpBrand = Symbol("CountOpBrand");
export const ViewBlockBrand = Symbol("ViewBlockBrand");
export const LineBrand = Symbol("LineBrand");
export const RelationViewBrand = Symbol("RelationViewBrand");
export const FormerUseBrand = Symbol("FormerUseBrand");
export const ReactionPartitionBrand = Symbol("ReactionPartitionBrand");
export function brand(value, marker) {
    Object.defineProperty(value, marker, { value: true, enumerable: false });
    return value;
}
export function hasBrand(value, marker) {
    return (typeof value === "object" &&
        value !== null &&
        value[marker] === true);
}
export function hasFuncBrand(value, marker) {
    return typeof value === "function" && value[marker] === true;
}
